import React from "react";
import axiosInstance from "../configurations/instance";

class ForgotPassword extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      email: "",
      message: "",
      error: "",
    };
  }

  handleInputChange = (event) => {
    this.setState({ email: event.target.value });
  };

  handleResetPassword = () => {
    const { email } = this.state;

    if (!email) {
      this.setState({ error: "Пожалуйста, введите почту!" });
      return;
    }

    axiosInstance
      .post("/auth/forgot-password", { email })
      .then((response) => {
        this.setState({
          message: "Ссылка для сброса пароля отправлена на вашу почту!",
          error: "",
        });
      })
      .catch((error) => {
        console.error("Ошибка при сбросе пароля:", error);
        this.setState({
          error: "Не удалось отправить ссылку. Проверьте почту и попробуйте снова.",
          message: "",
        });
      });
  };

  render() {
    const { email, message, error } = this.state;

    return (
      <div className="forgot-password-page">
        <h1>Забыли пароль?</h1>
        <h3>Введите вашу почту, чтобы получить ссылку для сброса пароля</h3>
        <div className="form-container">
          <input
            type="email"
            placeholder="Введите вашу почту"
            value={email}
            onChange={this.handleInputChange}
          />
          <button type="button" onClick={this.handleResetPassword}>
            Отправить
          </button>
          {message && <p className="success-message">{message}</p>}
          {error && <p className="error-message">{error}</p>}
        </div>
      </div>
    );
  }
}

export default ForgetPassword;
